import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => (await createHost()) as any;
const units = async (h: any) => { const { available, reserved } = await h.stock(); return { available, reserved }; };

test('initial state and restock cap', async () => {
  const h = await fresh();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: true });
  assert.deepEqual(await h.restock(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await units(h), { available: 3, reserved: 0 });
  assert.equal(await h.order('x'), null);
  assert.equal((await h.cancel('x')).ok, false);
});

test('place, messages, confirm', async () => {
  const h = await fresh();
  assert.equal((await h.place('a', 3)).ok, false);
  assert.equal((await h.place('a', 0)).ok, false);
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.place('a', 1), { ok: true });
  assert.equal((await h.place('a', 1)).ok, false);
  assert.deepEqual(await h.order('a'), { status: 'pending', qty: 1 });
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual({ ...msgs[0], id: undefined }, { id: undefined, from: 'a', to: 'inventory', action: 'Reserve', data: { from: 'a', qty: 1 } });
  await h.deliver(msgs[0].id);
  const [ans] = await h.inFlight();
  assert.deepEqual([ans.from, ans.to, ans.action, ans.data], ['inventory', 'a', 'Reserved', {}]);
  await h.deliverAll();
  assert.deepEqual(await h.order('a'), { status: 'confirmed', qty: 1 });
  assert.deepEqual(await units(h), { available: 0, reserved: 1 });
  assert.deepEqual(await h.cancel('a'), { ok: true });
  const [rel] = await h.inFlight();
  assert.deepEqual([rel.action, rel.data], ['Release', { qty: 1 }]);
  await h.deliverAll();
  assert.deepEqual(await units(h), { available: 1, reserved: 0 });
  assert.equal((await h.cancel('a')).ok, false);
});

test('expire', async () => {
  const h = await fresh();
  assert.equal((await h.expire('x')).ok, false);
  await h.place('a', 1);
  assert.equal((await h.expire('a')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.expire('a'), { ok: true });
  assert.deepEqual(await h.order('a'), { status: 'expired', qty: 1 });
  assert.equal((await h.expire('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
  const [rel] = await h.inFlight();
  assert.deepEqual([rel.action, rel.data], ['Release', { qty: 1 }]);
  await h.deliverAll();
  assert.deepEqual(await units(h), { available: 1, reserved: 0 });
});

test('out of stock and cancelling', async () => {
  const h = await fresh();
  await h.place('b', 2);
  await h.deliverAll();
  assert.deepEqual(await h.order('b'), { status: 'rejected', qty: 2 });
  assert.equal((await h.cancel('b')).ok, false);
  await h.place('c', 1);
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.deepEqual(await h.order('c'), { status: 'cancelling', qty: 1 });
  assert.equal((await h.cancel('c')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.order('c'), { status: 'cancelled', qty: 1 });
  assert.deepEqual(await units(h), { available: 1, reserved: 0 });
});

test('close and open', async () => {
  const h = await fresh();
  assert.equal((await h.open()).ok, false);
  await h.place('a', 1);
  await h.deliverAll();
  assert.deepEqual(await h.close(), { ok: true });
  assert.equal((await h.close()).ok, false);
  assert.equal((await h.restock()).ok, false);
  assert.deepEqual(await h.stock(), { available: 0, reserved: 1, open: false });
  await h.cancel('a');
  await h.deliverAll();
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  await h.place('b', 1);
  await h.deliverAll();
  assert.deepEqual(await h.order('b'), { status: 'rejected', qty: 1 });
  assert.deepEqual(await h.stock(), { available: 1, reserved: 0, open: false });
  assert.deepEqual(await h.open(), { ok: true });
  assert.deepEqual(await h.restock(), { ok: true });
  await h.place('c', 1);
  await h.deliverAll();
  assert.deepEqual(await h.order('c'), { status: 'confirmed', qty: 1 });
});

